class HelloViewModel : public Object, public virtual IHelloViewModel
{
private:
    WString name = L"world";
    WString welcome = L"Hello, world!";

public:
    WString GetName() override
    {
        return name;
    }

    void SetName(const WString& value) override
    {
        if (name != value)
        {
            name = value;
            welcome = L"Hello, " + name + L"!";
            NameChanged();
            WelcomeChanged();
        }
    }

    WString GetWelcome() override
    {
        return welcome;
    }
};

class HelloViewModel
{
    static func Create(): IHelloViewModel^
    {
        return new (IHelloViewModel^)
        {
            var name: string = "world";
            var welcome: string = "Hello, world!";

            override func GetName(): string
            {
                return name;
            }

            override func SetName(value: string): void
            {
                if (name != value)
                {
                    name = value;
                    welcome = $"Hello, $(name)!";
                    NameChanged();
                    WelcomeChanged();
                }
            }

            override func GetWelcome(): string
            {
                return welcome;
            }
        };
    }
}

class HelloViewModel implements IHelloViewModelLocal {
    private name = 'world';
    private welcome = 'Hello, world!';

    readonly NameChanged = new RpcEvent<[]>();
    readonly WelcomeChanged = new RpcEvent<[]>();

    GetName(): string {
        return this.name;
    }

    async SetName(value: string): Promise<void> {
        if (this.name !== value) {
            this.name = value;
            this.welcome = `Hello, ${this.name}!`;
            await this.NameChanged.emit();
            await this.WelcomeChanged.emit();
        }
    }

    GetWelcome(): string {
        return this.welcome;
    }
}
